PL = {10: '십', 100: '백', 1000: '천'}
def up(n, p): return -(-n // p) * p
def dn(n, p): return n // p * p
def rd(n, p): return (n + p // 2) // p * p

def build():
    b = Bank('range5')
    H_IN = '이상: 기준 수와 같거나 큰 수 / 이하: 기준 수와 같거나 작은 수 (기준 수 포함)'
    H_EX = '초과: 기준 수보다 큰 수 / 미만: 기준 수보다 작은 수 (기준 수 포함하지 않음)'
    H_UD = '올림: 구하려는 자리 아래 수를 올려서, 버림: 구하려는 자리 아래 수를 버려서 나타내요.'
    H_RD = '반올림: 구하려는 자리 바로 아래 숫자가 0~4이면 버리고, 5~9이면 올려요.'

    def cnt(qid, diff, lo, lw, hi, hw, word=None, unit='개', ask='count'):
        # lw/hw: 'in' 포함, 'ex' 포함 안 함
        a = lo if lw == 'in' else lo + 1; c = hi if hw == 'in' else hi - 1
        n = c - a + 1; s = sum(range(a, c + 1))
        names = {('in', 'lo'): '이상', ('ex', 'lo'): '초과', ('in', 'hi'): '이하', ('ex', 'hi'): '미만'}
        rng = f'{lo} {names[(lw, "lo")]} {hi} {names[(hw, "hi")]}'
        alts = []
        for la, ha in (('in', 'in'), ('ex', 'ex'), ('in', 'ex'), ('ex', 'in')):
            if (la, ha) == (lw, hw): continue
            aa = lo if la == 'in' else lo + 1; cc = hi if ha == 'in' else hi - 1
            alts.append((cc - aa + 1, sum(range(aa, cc + 1))))
        if ask == 'count':
            text = word or f'{rng}인 자연수는 모두 몇 개일까요?'
            cands = [(f'{x}{unit}', 'incl') for x, _ in alts] + [(f'{n + 1}{unit}', 'count'), (f'{n - 1}{unit}' if n > 1 else None, 'count'), (f'{hi - lo + 2}{unit}', 'count')]
            return Q(b, qid, diff, text, f'{n}{unit}', cands, H_IN if lw == hw == 'in' else H_EX if lw == hw == 'ex' else H_IN + ' / ' + H_EX,
                     f'범위의 가장 작은 자연수와 가장 큰 자연수를 먼저 찾아요.', f'{rng}인 자연수는 {a}부터 {c}까지로 모두 {n}{unit}예요.', f'첫 단계: {lo}와 {hi}가 범위에 들어가는지 확인해요')
        text = word or f'{rng}인 자연수를 모두 더하면 얼마일까요?'
        cands = [(str(y), 'incl') for _, y in alts] + [(str(s + c + 1), 'count'), (str(s - a), 'count')]
        return Q(b, qid, diff, text, str(s), cands, H_IN + ' / ' + H_EX, '범위에 드는 자연수를 모두 써 봐요.', f'{a}부터 {c}까지 더하면 {s}이에요.', f'첫 단계: {lo}와 {hi}가 범위에 들어가는지 확인해요')

    def mean_q(qid, diff, k, word):
        opts = {'이상': f'{k}와 같거나 큰 수', '이하': f'{k}와 같거나 작은 수', '초과': f'{k}보다 큰 수', '미만': f'{k}보다 작은 수'}
        tag = {('이상', '초과'): 'incl', ('이상', '이하'): 'dir', ('이상', '미만'): 'dir', ('이하', '미만'): 'incl', ('이하', '이상'): 'dir', ('이하', '초과'): 'dir',
               ('초과', '이상'): 'incl', ('초과', '미만'): 'dir', ('초과', '이하'): 'dir', ('미만', '이하'): 'incl', ('미만', '초과'): 'dir', ('미만', '이상'): 'dir'}
        return Q(b, qid, diff, f'{k} {word}인 수를 바르게 설명한 것은?', opts[word], [(v, tag[(word, w)]) for w, v in opts.items() if w != word],
                 H_IN if word in ('이상', '이하') else H_EX, f'{k}가 {word}인 수에 들어가는지 먼저 생각해요.', f'{k} {word}인 수는 {ieyo(opts[word])}.', f'첫 단계: 기준 수 {k}가 범위에 포함되는지 생각해요')

    def pick_q(qid, diff, text, ans, wrongs, hint, explain):
        return Q(b, qid, diff, text, ans, wrongs, hint, '기준 수를 포함하는지, 큰 쪽인지 작은 쪽인지 확인해요.', explain, '첫 단계: 기준 수와 각 보기를 비교해요')

