    def ud(qid, diff, n, p, mode, word=None, unit=''):
        ans = up(n, p) if mode == 'up' else dn(n, p)
        other = dn(n, p) if mode == 'up' else up(n, p)
        q2 = p * 10 if p * 10 <= 10 ** len(str(n)) else p // 10
        alt_p = up(n, q2) if mode == 'up' else dn(n, q2)
        cands = [(f'{other}{unit}', 'down'), (f'{rd(n, p)}{unit}', 'round'), (f'{alt_p}{unit}' if p * 10 <= n and alt_p > 0 else None, 'place'), (f'{(up(n, p // 10) if mode == "up" else dn(n, p // 10)) if p >= 100 else alt_p}{unit}', 'place'), (f'{n}{unit}', 'guess'), (f'{ans + p}{unit}', 'calc'), (f'{ans - p}{unit}' if ans > p else None, 'calc')]
        nm = '올림' if mode == 'up' else '버림'
        text = word or f'{n}을(를) {nm}하여 {PL[p]}의 자리까지 나타내면?'.replace('을(를)', '을' if str(n)[-1] in '013678' else '를')
        return Q(b, qid, diff, text, f'{ans}{unit}', cands, H_UD, f'{PL[p]}의 자리 아래 수를 {"올려요" if mode == "up" else "버려요"}.' if not word else '모자라지 않게 하려면 올림, 다 채운 것만 세려면 버림이에요.',
                 f'{n}을 {nm}하여 {PL[p]}의 자리까지 나타내면 {ans}이에요.' if not word else f'답은 {ans}{unit}예요.', f'첫 단계: {PL[p]}의 자리 아래에 있는 수를 찾아요' if not word else '첫 단계: 올림과 버림 중 어떤 방법이 알맞은지 정해요')

