    def ro_q(qid, diff, n, p, word=None, unit=''):
        ans = rd(n, p)
        digit0 = (n // (p // 10)) % 10
        cands = [(f'{up(n, p) if ans == dn(n, p) else dn(n, p)}{unit}', 'five' if digit0 in (4, 5) else 'down'),
                 (f'{rd(n, p * 10)}{unit}' if p * 10 <= n and rd(n, p * 10) > 0 else None, 'place'), (f'{rd(n, p // 10)}{unit}' if p >= 100 else None, 'place'), (f'{n}{unit}', 'guess'),
                 (f'{ans + p}{unit}', 'calc'), (f'{ans - p}{unit}' if ans > p else None, 'calc')]
        text = word or f'{n}을(를) 반올림하여 {PL[p]}의 자리까지 나타내면?'.replace('을(를)', '을' if str(n)[-1] in '013678' else '를')
        digit = (n // (p // 10)) % 10
        return Q(b, qid, diff, text, f'{ans}{unit}', cands, H_RD, f'{PL[p]}의 자리 바로 아래 숫자는 {digit}이에요.', f'바로 아래 숫자 {digit}가 {"5 이상이므로 올려서" if digit >= 5 else "5보다 작으므로 버려서"} {ans}{unit}이에요.',
                 f'첫 단계: {PL[p]}의 자리 바로 아래 자리의 숫자를 확인해요')

